import random
import string
import sys
from test.support import import_helper
pwd = import_helper.import_module('pwd')

def _t():
    try:
        pwd.getpwuid()
    except TypeError:
        pass
    try:
        pwd.getpwuid(*(3.14,))
    except TypeError:
        pass
    try:
        pwd.getpwuid(*(0.0,))
    except TypeError:
        pass
    try:
        pwd.getpwuid(*(0, 0))
    except TypeError:
        pass
    try:
        pwd.getpwuid(*(2 ** 128,))
    except KeyError:
        pass
    try:
        pwd.getpwuid(*(-2 ** 128,))
    except KeyError:
        pass
    try:
        pwd.getpwnam()
    except TypeError:
        pass
    try:
        pwd.getpwnam(*(42,))
    except TypeError:
        pass
    try:
        pwd.getpwnam(*(b'root',))
    except TypeError:
        pass
    try:
        pwd.getpwnam(*('root', 0))
    except TypeError:
        pass
    try:
        pwd.getpwnam(*('a\x00b',))
    except ValueError:
        pass
    try:
        pwd.getpwnam(*('root\x00',))
    except ValueError:
        pass
    try:
        pwd.getpwnam(*('roo\udc74',))
    except UnicodeEncodeError:
        pass
    try:
        pwd.getpwnam(*('',))
    except KeyError:
        pass
    try:
        pwd.getpwall(*(42,))
    except TypeError:
        pass
    for _ in range(30):
        fakename = ''.join(random.choices(string.ascii_lowercase, k=6))
        try:
            pwd.getpwnam(fakename)
        except KeyError:
            break
    else:
        raise AssertionError('Cannot find non-existent user name')
    maxuid = max((e.pw_uid for e in pwd.getpwall()))
    if maxuid < 2 ** 15:
        maxuid = 2 ** 15
    elif maxuid < 2 ** 16:
        maxuid = 2 ** 16 - 1
    else:
        maxuid = 2 ** 31
    for _ in range(30):
        fakeuid = random.randrange(maxuid)
        try:
            pwd.getpwuid(fakeuid)
        except KeyError:
            break
    else:
        raise AssertionError('Cannot find non-existent uid')
    if sys.platform != 'cygwin':
        try:
            pwd.getpwuid(*(-1,))
        except KeyError:
            pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
